// Generated by `pnpm nx g @app/generators:action messages.publish-history.list`. Requests go through the real router
// with createTestEngine().inject. They fail until createMessagesPublishHistoryListAction is implemented; do not weaken them.
import { messagesPublishHistoryList } from '@app/contracts';
import {
  createLogger,
  createManualClock,
  createRoleAuthorizer,
} from '@app/kernel';
import {
  createFakeSealer,
  createMemoryPublishHistory,
  createMessagesFakeDeps,
  createMessagesPublishHistoryListAction,
  createPublishHistory,
  type PublishRecord,
} from '@app/svc-messages';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

const subject = () =>
  createMessagesPublishHistoryListAction(createMessagesFakeDeps());
const def = messagesPublishHistoryList;
const record = (ownerId: string, over: Partial<PublishRecord> = {}) => ({
  ownerId,
  connectionId: 'c1',
  vhost: '/',
  at: 1_700_000_000_000,
  exchange: '',
  routingKey: 'orders',
  copies: 1,
  summary: {
    confirmed: 1,
    nacked: 0,
    returned: 0,
    blocked: 0,
    timeout: 0,
    failed: 0,
    'not-sent': 0,
  },
  props: { contentType: 'text/plain' },
  body: new TextEncoder().encode('hello'),
  ...over,
});

/** A history store over the fakes of the module; the spec records into it as the engine's principal. */
function createStore() {
  let n = 0;
  return createPublishHistory({
    history: createMemoryPublishHistory(),
    sealer: createFakeSealer(),
    newId: () => {
      n += 1;
      return `entry-${String(n)}`;
    },
    clock: createManualClock(1_700_000_000_000),
    logger: createLogger({ level: 'silent' }),
  });
}

let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('GET /connections/{cid}/messages/publish-history', () => {
  it('route 1: the route runs messages.publish-history.list and answers in the shape of the contract', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/messages/publish-history',
    });

    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
    expect(answer.json()).toEqual({ entries: [] });
  });

  it('route 1b: a query string is read as numbers and text, and a cursor continues the window', async () => {
    const store = createStore();
    engine = createTestEngine({
      actions: [createMessagesPublishHistoryListAction({ store })],
    });
    for (const key of ['a', 'b', 'c']) {
      await store.record(
        record(engine.principal.id, {
          routingKey: key,
          at: 1_700_000_000_000 + key.charCodeAt(0),
        }),
      );
    }
    await store.record(record('someone-else', { routingKey: 'theirs' }));
    const get = async (query: string) =>
      (
        await engine.inject({
          method: 'GET',
          path: `/connections/c1/messages/publish-history${query}`,
        })
      ).json<{ entries: { routingKey: string }[]; nextCursor?: string }>();

    const first = await get('?limit=2');
    const second = await get(
      `?limit=2&cursor=${encodeURIComponent(first.nextCursor ?? '')}`,
    );
    const since = await get(`?from=${String(1_700_000_000_000 + 98)}`);
    const prefixed = await get('?routingKeyPrefix=b&exchange=');

    expect(first.entries.map((entry) => entry.routingKey)).toEqual(['c', 'b']);
    expect(first.nextCursor).toBeDefined();
    expect(second.entries.map((entry) => entry.routingKey)).toEqual(['a']);
    expect(second.nextCursor).toBeUndefined();
    expect(since.entries.map((entry) => entry.routingKey)).toEqual(['c', 'b']);
    expect(prefixed.entries.map((entry) => entry.routingKey)).toEqual(['b']);
  });

  it('route 1c: a limit over 200 is a 400 Problem', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/messages/publish-history?limit=201',
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
  });

  it('route 2: a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/messages/publish-history',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('route 3: a caller that does not hold messages.publish gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/messages/publish-history',
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('route 4: input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/messages/publish-history?unexpected=1',
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('route 5: another method on the same path is 405', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'DELETE',
      path: '/connections/c1/messages/publish-history',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('GET');
  });
});
